def compute(n):
    try:
        try: return 12 // n
        finally: print('inner', n)
    finally: print('outer', n)
print(compute(3))
try: compute(0)
except ZeroDivisionError: print('zero')

def outer():
    count = 0
    def compute(n):
        nonlocal count
        try:
            count += 1
            return count, 12 // n
        finally: print('closed', count)
    print(compute(3))
    try: compute(0)
    except ZeroDivisionError: print('zero', count)
    print(compute(2))
outer()

def compute(n):
    total = 0
    for value in range(n):
        try:
            total += value + 1
            if value % 2 == 0: continue
            if value > 4: break
        finally: print('closed', value)
    return total
print(compute(8))

def compute(n):
    try: return 12 // n
    finally: int('broken')
for n in [0, 3]:
    try: compute(n)
    except ValueError as error:
        print(None if error.__context__ is None else type(error.__context__).__name__)

def compute(n):
    try:
        try: return 12 // n
        except ZeroDivisionError: return 'zero'
    finally: print('closed', n)
print(compute(3), compute(0))

